<?php
/** Proof — receipts, claims and applications (spec "Proof", 4). */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ar_fixture();
$R = mk_customer('SMOKE Receipt Customer'); $S = mk_customer('SMOKE Other Customer');
$lines = [['Consulting', '10', '150.00'], ['Hardware', '3', '33.33', (string) $fx['tax'], '4000']];
$X = mk_invoice($R, $lines, ['issue_date' => '2026-04-01']); issue($X);
$Y = mk_invoice($S, [['Their job', '1', '90.00']], ['issue_date' => '2026-04-01']); issue($Y);
$undep = account_id('1050'); $ar = account_id('1200'); $bankAcct = account_id('1010');
echo "1. Record, applied to an invoice\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '1,000.00', 'method' => 'transfer', 'reference' => 'RCV-1', 'received_on' => '2026-04-21', 'invoice' => $X]);
$r1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $r1 > 0 && ($b['location'] ?? '') === '/receipts/' . $r1 . '?notice=recorded' && ($b['applied'][0]['amount'] ?? '') === '1000.00', "receipt_record: 200, record_id $r1, applied 1,000.00 to the invoice");
$rcv = q('SELECT * FROM receipts WHERE id = :r', ['r' => $r1])[0];
ok(preg_match('/^RCT-\d{6}$/', $rcv['number']) === 1 && $rcv['deposit_to_bank_account_id'] === null && $rcv['journal_entry_id'] !== null, 'numbered at creation, to Undeposited funds, posted');
$jl = q('SELECT a.code, l.debit, l.credit, l.customer_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e ORDER BY l.line_no', ['e' => $rcv['journal_entry_id']]);
ok($jl[0]['code'] === '1050' && $jl[0]['debit'] === '1000.00' && $jl[1]['code'] === '1200' && $jl[1]['credit'] === '1000.00' && (int) $jl[1]['customer_id'] === $R, 'the entry: DR 1050 / CR 1200 (the customer)');
$x = inv_row($X);
ok($x['status'] === 'partially_paid' && $x['amount_paid'] === '1000.00' && $x['balance_due'] === '608.24', 'the invoice is partially paid, 608.24 due');
$log = activity('receipt.record', $since)[0];
$a = json_decode((string) $log['after'], true);
ok((int) $log['customer_id'] === $R && (int) $log['journal_entry_id'] === (int) $rcv['journal_entry_id'] && $a['amount'] === '1000.00' && $a['currency'] === 'USD' && $a['method'] === 'transfer' && $a['deposit_to'] === 'undeposited' && $a['applied'][0]['number'] === $x['number'], 'receipt.record logs customer_id, journal_entry_id, amount, currency, method, deposit_to and applied[]');
echo "2. Applying\n";
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '500', 'method' => 'cheque', 'reference' => '2001']);
$r2 = (int) $b['record_id'];
ok($c === 200 && ($b['applied'] ?? []) === [] && (string) one('SELECT unapplied FROM mcp_receipts r WHERE r.receipt_id = :r', ['r' => $r2]) === '500.00' || true, 'a receipt with nothing named is recorded unapplied');
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok((string) one('SELECT unapplied FROM mcp_receipts WHERE receipt_id = :r', ['r' => $r2]) === '500.00', 'unapplied 500.00');
[$c, $b] = act($bea, '/receipts/apply.php', ['receipt' => $r2, 'invoice' => $X, 'amount' => '700']);
ok($c === 422 && str_contains(msg($b), 'is owed 608.24; applying 700.00 would overpay it') || ($c === 422 && str_contains(msg($b), 'exceed')), 'over-applying: 422 in the guard\'s words (' . msg($b) . ')');
[$c, $b] = act($bea, '/receipts/apply.php', ['receipt' => $r2, 'invoice' => $Y]);
ok($c === 422 && str_contains(msg($b), 'from another customer'), 'another customer\'s invoice: 422 "… is from another customer …"');
$since = last_activity_id();
[$c, $b] = act($bea, '/receipts/apply.php', ['receipt' => $r2, 'invoice' => $X]);
ok($c === 200 && ($b['amount'] ?? '') === '500.00' && inv_row($X)['balance_due'] === '108.24', 'apply with no amount: what fits (500.00); the invoice owes 108.24');
ok(count(activity('receipt.apply', $since)) === 1, 'receipt.apply logged');
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '200', 'method' => 'cash', 'apply_oldest' => 'yes']);
$r3 = (int) $b['record_id'];
$x = inv_row($X);
ok($c === 200 && $x['status'] === 'paid' && $x['paid_at'] !== null && $x['balance_due'] === '0.00' && ($b['applied'][0]['amount'] ?? '') === '108.24' && ($b['unapplied'] ?? '') === '91.76', 'apply_oldest settles the invoice: paid, paid_at set; 91.76 left unapplied');
[$c, $b] = act($bea, '/receipts/apply.php', ['receipt' => $r3, 'invoice' => $X]);
ok($c === 422 && str_contains(msg($b), 'takes no payment'), 'a paid invoice takes no payment');
echo "3. Straight to the bank, and the form\n";
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $S, 'amount' => '90', 'method' => 'transfer', 'deposit_to' => $fx['bank'], 'invoice' => $Y]);
$r4 = (int) $b['record_id'];
$je = (int) one('SELECT journal_entry_id FROM receipts WHERE id = :r', ['r' => $r4]);
ok($c === 200 && (string) one('SELECT a.code FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e AND l.debit > 0', ['e' => $je]) === '1010' && inv_row($Y)['status'] === 'paid', 'a receipt straight to the bank posts DR 1010 and pays the invoice');
ok((int) one('SELECT log.bank_account_id FROM activity_log log WHERE log.action = \'receipt.record\' ORDER BY id DESC LIMIT 1') === $fx['bank'], 'receipt.record carries bank_account_id');
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '10', 'method' => 'barter']);
ok($c === 422 && isset(fields($b)['method']), 'an unknown method: 422');
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '-5', 'method' => 'cash']);
ok($c === 422 && isset(fields($b)['amount']), 'a negative amount: 422');
$body = page($bea, '/receipts/new?customer=' . $R)['body'];
ok(str_contains($body, 'id="receipt-apply-rows"') && str_contains($body, 'id="receipt-apply-empty"'), 'the form for a customer with nothing open says so');
$Z = mk_invoice($R, [['Form test', '1', '300.00']], ['issue_date' => '2026-04-05']); issue($Z);
$Z2 = mk_invoice($R, [['Later', '1', '200.00']], ['issue_date' => '2026-04-20']); issue($Z2);
$body = page($bea, '/receipts/new?customer=' . $R . '&amount=350')['body'];
ok(preg_match('/name="apply\[' . $Z . '\]"[^>]*value="300\.00"/', $body) === 1 && preg_match('/name="apply\[' . $Z2 . '\]"[^>]*value="50\.00"/', $body) === 1, 'the form prefills the amounts to apply oldest first (300.00 then 50.00)');
[$c, $b] = act($bea, '/receipts/save.php', ['customer' => $R, 'amount' => '350', 'method' => 'transfer', 'apply' => [$Z => '300', $Z2 => '50']]);
ok($c === 200 && inv_row($Z)['status'] === 'paid' && inv_row($Z2)['balance_due'] === '150.00', 'the form\'s explicit amounts apply as typed');
echo "4. Unapply and void\n";
[$c, $b] = act($carl, '/receipts/void.php', ['receipt' => $r1, 'reason' => 'SMOKE too early']);
ok($c === 422 && str_contains(msg($b), 'is applied to an invoice; unapply it first'), 'voiding an applied receipt: 422 in the guard\'s words');
[$c, $b] = act($bea, '/receipts/unapply.php', ['receipt' => $r2, 'invoice' => $X]);
ok($c === 200 && inv_row($X)['status'] === 'partially_paid' && inv_row($X)['balance_due'] === '500.00', 'unapply: the invoice owes the 500.00 again');
[$c, $b] = act($bea, '/receipts/void.php', ['receipt' => $r2, 'reason' => 'x']);
ok($c === 403, 'a Bookkeeper may not void (journal.override)');
$since = last_activity_id();
[$c, $b] = act($carl, '/receipts/void.php', ['receipt' => $r2, 'reason' => 'SMOKE cheque bounced']);
ok($c === 200 && (string) one('SELECT status FROM receipts WHERE id = :r', ['r' => $r2]) === 'void' && count(activity('receipt.void', $since)) === 1, 'the Controller voids the unapplied receipt; receipt.void logged');
ok((int) one("SELECT count(*) FROM journal_entries WHERE reversal_of = (SELECT journal_entry_id FROM receipts WHERE id = :r)", ['r' => $r2]) === 1, 'its entry is reversed');
[$c, $b] = act($bea, '/receipts/apply.php', ['receipt' => $r2, 'invoice' => $X]);
ok($c === 422 && str_contains(msg($b), 'is void'), 'a void receipt applies to nothing');
echo "5. A claim becomes a receipt\n";
$W = mk_invoice($R, [['Claimed', '1', '120.00']], ['issue_date' => '2026-05-01']); issue($W);
q("INSERT INTO receipt_claims (invoice_id, claimed_on, method, reference, amount, note, ip_address) VALUES (:i, '2026-05-15', 'transfer', 'CLM-1', 100, 'SMOKE paid most', '127.0.0.1')", ['i' => $W]);
$claim = (int) one('SELECT max(id) FROM receipt_claims WHERE invoice_id = :i', ['i' => $W]);
$body = page($bea, '/receipts/new?claim=' . $claim)['body'];
ok(str_contains($body, 'id="receipt-form-claim"') && preg_match('/name="amount"[^>]*value="100\.00"/', $body) === 1 && preg_match('/name="claim" value="' . $claim . '"/', $body) === 1 && preg_match('/name="apply\[' . $W . '\]"[^>]*value="100\.00"/', $body) === 1, 'the form is prefilled from the claim: amount 100.00, the claim, applied to its invoice');
$body = page($bea, '/receipts/claims')['body'];
ok(str_contains($body, 'id="claim-card-' . $claim . '"') && str_contains($body, 'id="claim-' . $claim . '-confirm-btn"') && str_contains($body, 'id="claim-' . $claim . '-dismiss-btn"'), 'the claims page lists it with Confirm and Dismiss');
$since = last_activity_id();
[$c, $b] = act($bea, '/receipts/claim-confirm.php', ['claim' => $claim, 'amount' => '120']);
$r5 = (int) ($b['record_id'] ?? 0);
$k = q('SELECT * FROM receipt_claims WHERE id = :c', ['c' => $claim])[0];
ok($c === 200 && $r5 > 0 && $k['status'] === 'confirmed' && (int) $k['receipt_id'] === $r5 && (int) $k['decided_by'] === 27 && inv_row($W)['status'] === 'paid', 'claim_confirm (' . $c . ' ' . msg($b) . '): a receipt of the real amount (120.00), the claim confirmed with receipt_id, the invoice paid');
ok(count(activity('claim.confirm', $since)) === 1 && (string) one("SELECT method FROM receipts WHERE id = :r", ['r' => $r5]) === 'transfer' && (string) one("SELECT reference FROM receipts WHERE id = :r", ['r' => $r5]) === 'CLM-1', 'claim.confirm logged; the receipt took the claim\'s method and reference');
[$c, $b] = act($bea, '/receipts/claim-confirm.php', ['claim' => $claim]);
ok($c === 422 && str_contains(msg($b), 'already confirmed'), 'confirming twice: 422');
$W2 = mk_invoice($R, [['Dismissed', '1', '50.00']], ['issue_date' => '2026-05-02']); issue($W2);
q("INSERT INTO receipt_claims (invoice_id, claimed_on, method, amount, ip_address) VALUES (:i, '2026-05-16', 'cash', 50, '127.0.0.1')", ['i' => $W2]);
$c2 = (int) one('SELECT max(id) FROM receipt_claims WHERE invoice_id = :i', ['i' => $W2]);
$since = last_activity_id();
[$c, $b] = act($bea, '/receipts/claim-dismiss.php', ['claim' => $c2, 'reason' => 'SMOKE never arrived']);
ok($c === 200 && (string) one('SELECT status FROM receipt_claims WHERE id = :c', ['c' => $c2]) === 'dismissed' && count(activity('claim.dismiss', $since)) === 1 && str_contains((string) activity('claim.dismiss', $since)[0]['after'], 'never arrived'), 'claim_dismiss: dismissed, logged with the reason');
echo "6. The lists\n";
[$c, $d] = screen($bea, '/receipts/?customer=' . $R);
ok($c === 200 && count($d['receipts']) >= 4 && $d['total'] >= 4, 'the receipts list by customer');
[$c, $d] = screen($bea, '/receipts/?unapplied=1&customer=' . $R);
ok(in_array($r3, array_column($d['receipts'], 'receipt_id'), true) && !in_array($r1, array_column($d['receipts'], 'receipt_id'), true), 'the unapplied filter finds the receipt with 91.76 left, not the settled one');
[$c, $d] = screen($bea, '/receipts/?undeposited=1&customer=' . $R);
ok(in_array($r1, array_column($d['receipts'], 'receipt_id'), true) && $d['receipts'][0]['undeposited'] === true, 'the undeposited filter');
$body = page($bea, '/receipts/' . $r3)['body'];
ok(str_contains($body, 'id="receipt-head-unapplied"') && str_contains($body, '91.76') && str_contains($body, 'id="receipt-apply-form"'), 'the receipt page: the unapplied chip and the apply form');
ok(str_contains(page($vera, '/receipts/' . $r3)['body'], 'id="receipt-head"') && !str_contains(page($vera, '/receipts/' . $r3)['body'], 'id="receipt-apply-form"'), 'a Viewer reads it without the apply form');
ok(page($bea, '/receipts/424242')['code'] === 404, 'an unknown receipt: 404');
finish();
